from datetime import date
import pytest
from late_fee import LateFeeCalculator

MON = date(2026, 8, 3)  # Monday


def calc(today):
    return LateFeeCalculator(today=today)


def test_default_today():
    assert LateFeeCalculator()._today == date.today()


@pytest.mark.parametrize("bal", [0, -100])
def test_nonpositive_balance(bal):
    assert calc(date(2030, 1, 1)).compute_fee_cents(bal, MON) == 0


def test_today_before_due():
    assert calc(date(2026, 7, 1)).compute_fee_cents(10000, MON) == 0


def test_within_grace():
    # 14 calendar days = 10 weekdays -> no billable days
    assert calc(date(2026, 8, 17)).compute_fee_cents(10000, MON) == 0


def test_weekends_excluded():
    # Fri -> following Mon counts only Fri, so not past grace
    assert calc(date(2026, 8, 7)).compute_fee_cents(10000, MON) == 0


def test_minimum_fee():
    # 1 billable day: 5 cents -> min 500
    assert calc(date(2026, 8, 18)).compute_fee_cents(10000, MON) == 500


def test_normal_fee():
    # 20 weekdays, 10 billable: 1,000,000 * 0.0005 * 10 = 5000
    assert calc(date(2026, 8, 31)).compute_fee_cents(1_000_000, MON) == 5000


def test_cap_applies():
    fee = calc(date(2026, 9, 21)).compute_fee_cents(10000, date(2020, 1, 6))
    assert fee == 2500


def test_min_beats_cap():
    fee = calc(date(2026, 9, 21)).compute_fee_cents(1000, date(2020, 1, 6))
    assert fee == 500
